CREATE OR REPLACE FUNCTION public.can_intranet_action(p_page text,p_action text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); profile public.profiles%ROWTYPE; definition jsonb; role_keys text[]; chosen text; saved_count integer; permitted boolean; canonical_saved boolean; read_only boolean; level text;
BEGIN
 IF actor IS NULL OR p_action IS NULL OR p_action NOT IN ('read','create','update','delete','publish','validate','administer') THEN RETURN false; END IF;
 SELECT m.definition INTO definition FROM public.intranet_modules m WHERE page_id=p_page OR coalesce(m.definition->'permissionAliases','[]'::jsonb)?p_page;
 IF definition IS NULL THEN RETURN false; END IF;
 p_page:=definition->>'id';
 SELECT * INTO profile FROM public.profiles WHERE id=actor;
 IF NOT FOUND OR profile.app_origin IS DISTINCT FROM 'connect' OR profile.hr_status IS DISTINCT FROM 'active' OR NOT public.is_intranet_staff(actor) THEN RETURN false; END IF;
 IF public.has_role(actor,'admin') THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM public.access_interfaces WHERE (interface_key=p_page OR (coalesce(definition->'permissionAliases','[]'::jsonb)?interface_key AND NOT EXISTS(SELECT 1 FROM public.access_interfaces c WHERE c.interface_key=p_page AND c.status='active'))) AND status IS DISTINCT FROM 'active') THEN RETURN false; END IF;
 SELECT coalesce(array_agg(DISTINCT ar.role_key),'{}'::text[]),coalesce(bool_and(ar.read_only),false) INTO role_keys,read_only
 FROM public.access_assignments aa JOIN public.access_roles ar ON ar.id=aa.role_id AND ar.status='active'
 WHERE aa.employee_id=actor AND aa.status='active' AND (aa.starts_at IS NULL OR aa.starts_at<=now()) AND (aa.ends_at IS NULL OR aa.ends_at>=now());
 IF cardinality(role_keys)=0 THEN
  IF EXISTS(SELECT 1 FROM public.access_assignments WHERE employee_id=actor) THEN RETURN false; END IF;
  chosen:=public.legacy_hr_publication_role(profile.position::text,profile.poles::text[]);
  IF chosen IS NULL THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM public.access_roles WHERE role_key=chosen AND status IS DISTINCT FROM 'active') THEN RETURN false; END IF;
  role_keys:=ARRAY[chosen];
  SELECT coalesce(bool_or(ar.read_only),false) INTO read_only FROM public.access_roles ar WHERE ar.role_key=chosen;
 END IF;
 IF read_only AND p_action<>'read'THEN RETURN false;END IF;
 SELECT EXISTS(SELECT 1 FROM public.access_permissions ap JOIN public.access_roles r ON r.id=ap.role_id AND r.status='active'
 JOIN public.access_interfaces i ON i.id=ap.interface_id AND i.interface_key=p_page AND i.status='active'WHERE r.role_key=ANY(role_keys))INTO canonical_saved;
 SELECT count(*),coalesce(bool_or(ap.allowed AND a.action_key=p_action),false) INTO saved_count,permitted
 FROM public.access_permissions ap JOIN public.access_roles r ON r.id=ap.role_id AND r.status='active'
 JOIN public.access_interfaces i ON i.id=ap.interface_id AND (i.interface_key=p_page OR (NOT canonical_saved AND coalesce(definition->'permissionAliases','[]'::jsonb)?i.interface_key)) AND i.status='active'
 JOIN public.access_actions a ON a.id=ap.action_id WHERE r.role_key=ANY(role_keys);
 IF saved_count>0 THEN RETURN permitted; END IF;
 IF coalesce((definition->>'public')::boolean,false) THEN RETURN p_action IN ('read','create'); END IF;
 IF NOT coalesce((definition->>'transversal')::boolean,false) AND NOT (definition->>'scope'=ANY(profile.poles::text[])) THEN RETURN false; END IF;
 IF jsonb_array_length(definition->'restrictedRoles')>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(definition->'restrictedRoles') r WHERE r=ANY(role_keys)) THEN RETURN false; END IF;
 IF definition->>'scope'='admin' AND jsonb_array_length(definition->'restrictedRoles')=0 THEN RETURN false; END IF;
 IF p_action='read' THEN RETURN true; END IF;
 IF read_only THEN RETURN false; END IF;
 level:=coalesce(profile.seniority::text,'junior');
 RETURN CASE WHEN p_action IN ('create','update') THEN level IN ('mid','senior','lead','executive')
 WHEN p_action IN ('delete','validate') THEN level IN ('senior','lead','executive')
 WHEN p_action='publish' THEN level IN ('lead','executive') ELSE level='executive' END;
END;
$$;
CREATE OR REPLACE FUNCTION public.get_intranet_permissions()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_object_agg(m.page_id,(SELECT jsonb_object_agg(a,public.can_intranet_action(m.page_id,a)) FROM unnest(ARRAY['read','create','update','delete','publish','validate','administer'])a)),'{}'::jsonb) FROM public.intranet_modules m;
$$;
CREATE POLICY intranet_modules_staff ON public.intranet_modules FOR SELECT TO authenticated USING(public.is_intranet_staff(auth.uid()));

CREATE TABLE public.intranet_records (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id text NOT NULL REFERENCES public.intranet_modules(page_id),title text NOT NULL,
 payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','reviewed','approved','rejected','archived')),
 priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','critical')),
 owner_id uuid REFERENCES public.profiles(id),due_date date,visibility text NOT NULL DEFAULT 'pole' CHECK(visibility IN ('pole','restricted')),
 document_ids uuid[] NOT NULL DEFAULT '{}',created_by uuid NOT NULL REFERENCES public.profiles(id),test_account boolean NOT NULL,
 revision bigint NOT NULL DEFAULT 1,first_reviewer uuid REFERENCES public.profiles(id),approved_by uuid REFERENCES public.profiles(id),
 creation_key uuid NOT NULL,creation_request jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(created_by,creation_key));
CREATE TABLE public.intranet_record_events(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL REFERENCES public.intranet_records(id),actor_id uuid NOT NULL REFERENCES public.profiles(id),
 kind text NOT NULL,note text,before_state jsonb,after_state jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX intranet_records_page ON public.intranet_records(page_id,test_account,updated_at DESC,id);
CREATE INDEX intranet_events_record ON public.intranet_record_events(record_id,created_at,id);
ALTER TABLE public.intranet_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.intranet_record_events ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.intranet_records,public.intranet_record_events TO authenticated;
GRANT ALL ON public.intranet_records,public.intranet_record_events TO service_role;
CREATE OR REPLACE FUNCTION public.can_read_intranet_record(p public.intranet_records)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT public.can_intranet_action(p.page_id,'read') AND EXISTS(SELECT 1 FROM public.profiles me WHERE me.id=auth.uid() AND coalesce(me.test_account,false)=p.test_account)
 AND (p.visibility='pole' OR p.created_by=auth.uid() OR p.owner_id=auth.uid() OR public.can_intranet_action(p.page_id,'validate'));
$$;
CREATE POLICY intranet_records_read ON public.intranet_records FOR SELECT TO authenticated USING(public.can_read_intranet_record(intranet_records));
CREATE POLICY intranet_events_read ON public.intranet_record_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.intranet_records r WHERE r.id=record_id AND public.can_read_intranet_record(r)));

CREATE OR REPLACE FUNCTION public.validate_intranet_payload(p_page text,p_payload jsonb)
RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE fields jsonb; f jsonb; v jsonb; k text; line jsonb; s text;
BEGIN
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>100000 THEN RAISE EXCEPTION 'invalid_module_payload' USING ERRCODE='22023'; END IF;
 SELECT definition->'fields' INTO fields FROM public.intranet_modules WHERE page_id=p_page;
 IF fields IS NULL THEN RAISE EXCEPTION 'unknown_module' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_payload) LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fields) field_definition WHERE field_definition->>'key'=k) THEN RAISE EXCEPTION 'unknown_module_field' USING ERRCODE='22023'; END IF;
 END LOOP;
 FOR f IN SELECT value FROM jsonb_array_elements(fields) LOOP
  v:=p_payload->(f->>'key');s:=p_payload->>(f->>'key');
  IF coalesce((f->>'required')::boolean,false) AND (v IS NULL OR v='null'::jsonb OR btrim(coalesce(s,''))='') THEN RAISE EXCEPTION 'required_module_field:%',f->>'key' USING ERRCODE='22023'; END IF;
  IF v IS NULL OR v='null'::jsonb OR s='' THEN CONTINUE; END IF;
  IF f->>'type'='number' THEN
   IF jsonb_typeof(v)<>'number' OR s::numeric<0 OR s::numeric>1000000000000 THEN RAISE EXCEPTION 'invalid_module_number' USING ERRCODE='22023'; END IF;
  ELSIF f->>'type'='lines' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 THEN RAISE EXCEPTION 'invalid_module_lines' USING ERRCODE='22023'; END IF;
   FOR line IN SELECT value FROM jsonb_array_elements(v) LOOP
    IF jsonb_typeof(line)<>'object' OR length(coalesce(line->>'label','')) NOT BETWEEN 1 AND 255
    OR jsonb_typeof(line->'quantity') IS DISTINCT FROM 'number' OR jsonb_typeof(line->'amount') IS DISTINCT FROM 'number'
    OR (line->>'quantity')::numeric<0 OR (line->>'amount')::numeric<0 THEN RAISE EXCEPTION 'invalid_module_line' USING ERRCODE='22023'; END IF;
   END LOOP;
  ELSE
   IF jsonb_typeof(v)<>'string' OR char_length(s)>20000 THEN RAISE EXCEPTION 'invalid_module_text' USING ERRCODE='22023'; END IF;
   IF f->>'type'='date' THEN
    IF s !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'invalid_module_date' USING ERRCODE='22023'; END IF;
    BEGIN PERFORM s::date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid_module_date' USING ERRCODE='22023'; END;
   END IF;
   IF f->>'type'='email' AND s !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'invalid_module_email' USING ERRCODE='22023'; END IF;
  END IF;
 END LOOP;
END;
$$;
CREATE OR REPLACE FUNCTION public.list_intranet_people()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',concat_ws(' ',p.first_name,p.last_name)) ORDER BY p.first_name,p.last_name),'[]'::jsonb)
 FROM public.profiles p WHERE public.is_intranet_staff(auth.uid()) AND p.app_origin='connect' AND p.hr_status='active' AND coalesce(p.test_account,false)=coalesce((SELECT test_account FROM public.profiles WHERE id=auth.uid()),false)
 AND public.is_intranet_staff(p.id);
$$;
CREATE OR REPLACE FUNCTION public.list_intranet_records(p_page text,p_search text DEFAULT '',p_status text DEFAULT 'open',p_offset integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb; total integer; stats jsonb;
BEGIN
 IF NOT public.can_intranet_action(p_page,'read') THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_offset>100000 OR char_length(coalesce(p_search,''))>200 THEN RAISE EXCEPTION 'invalid_module_search' USING ERRCODE='22023'; END IF;
 SELECT count(*),jsonb_build_object('total',count(*),'draft',count(*)FILTER(WHERE status='draft'),'submitted',count(*)FILTER(WHERE status IN ('submitted','reviewed')),'approved',count(*)FILTER(WHERE status='approved')) INTO total,stats
 FROM public.intranet_records r WHERE r.page_id=p_page AND public.can_read_intranet_record(r);
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.updated_at DESC,x.id),'[]'::jsonb) INTO result FROM (
 SELECT r.* FROM public.intranet_records r WHERE r.page_id=p_page AND public.can_read_intranet_record(r)
 AND (coalesce(p_search,'')='' OR r.title ILIKE '%'||p_search||'%' OR r.payload::text ILIKE '%'||p_search||'%')
 AND (p_status='all' OR (p_status='open' AND r.status<>'archived') OR r.status=p_status)
 ORDER BY r.updated_at DESC,r.id LIMIT 50 OFFSET p_offset)x;
 RETURN jsonb_build_object('rows',result,'stats',stats,'has_more',jsonb_array_length(result)=50);
END;
$$;
CREATE OR REPLACE FUNCTION public.save_intranet_record(p_id uuid,p_page text,p_expected_revision bigint,p_key uuid,p_title text,p_payload jsonb,p_owner uuid,p_due date,p_priority text,p_visibility text,p_documents uuid[] DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); original public.intranet_records%ROWTYPE; saved public.intranet_records%ROWTYPE; requested jsonb;
BEGIN
 IF NOT public.can_intranet_action(p_page,'read') OR NOT public.can_intranet_action(p_page,CASE WHEN p_id IS NULL THEN 'create' ELSE 'update' END) THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
 IF length(btrim(coalesce(p_title,''))) NOT BETWEEN 1 AND 255 OR p_priority IS NULL OR p_priority NOT IN ('low','medium','high','critical') OR p_visibility IS NULL OR p_visibility NOT IN ('pole','restricted')
 OR p_documents IS NULL OR cardinality(p_documents)>30 OR array_position(p_documents,NULL) IS NOT NULL THEN RAISE EXCEPTION 'invalid_module_record' USING ERRCODE='22023'; END IF;
 PERFORM public.validate_intranet_payload(p_page,p_payload);
 IF p_owner IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=p_owner AND p.app_origin='connect' AND p.hr_status='active' AND public.is_intranet_staff(p.id)
 AND coalesce(p.test_account,false)=coalesce((SELECT test_account FROM public.profiles WHERE id=actor),false)) THEN RAISE EXCEPTION 'module_owner_forbidden' USING ERRCODE='42501'; END IF;
 -- Document authorization is installed by migration 0040 before any attachment can be saved.
 IF cardinality(p_documents)>0 AND to_regclass('public.intranet_drive_documents') IS NULL THEN RAISE EXCEPTION 'module_documents_unavailable' USING ERRCODE='42501'; END IF;
 IF cardinality(p_documents)>0 THEN
  IF EXISTS(SELECT 1 FROM unnest(p_documents)d WHERE NOT EXISTS(SELECT 1 FROM public.intranet_drive_documents x WHERE x.id=d AND public.can_read_intranet_drive_document(x))) THEN RAISE EXCEPTION 'module_documents_forbidden' USING ERRCODE='42501'; END IF;
 END IF;
 requested:=jsonb_build_object('page',p_page,'title',btrim(p_title),'payload',p_payload,'owner',p_owner,'due',p_due,'priority',p_priority,'visibility',p_visibility,'documents',p_documents);
 IF p_id IS NULL THEN
  IF p_key IS NULL OR p_expected_revision IS NOT NULL THEN RAISE EXCEPTION 'invalid_module_creation' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||p_key::text,0));
  SELECT * INTO saved FROM public.intranet_records WHERE created_by=actor AND creation_key=p_key;
  IF FOUND THEN IF saved.creation_request<>requested THEN RAISE EXCEPTION 'module_creation_key_conflict' USING ERRCODE='40001'; END IF; RETURN to_jsonb(saved); END IF;
  INSERT INTO public.intranet_records(page_id,title,payload,owner_id,due_date,priority,visibility,document_ids,created_by,test_account,creation_key,creation_request)
  VALUES(p_page,btrim(p_title),p_payload,p_owner,p_due,p_priority,p_visibility,p_documents,actor,coalesce((SELECT test_account FROM public.profiles WHERE id=actor),false),p_key,requested) RETURNING * INTO saved;
 ELSE
  SELECT * INTO original FROM public.intranet_records WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR original.page_id<>p_page OR NOT public.can_read_intranet_record(original) THEN RAISE EXCEPTION 'module_record_not_found' USING ERRCODE='42501'; END IF;
  IF p_expected_revision IS NULL OR original.revision<>p_expected_revision THEN RAISE EXCEPTION 'module_record_changed' USING ERRCODE='40001'; END IF;
  IF original.status NOT IN ('draft','rejected') THEN RAISE EXCEPTION 'module_record_locked' USING ERRCODE='55000'; END IF;
  IF actor NOT IN (original.created_by,coalesce(original.owner_id,original.created_by)) AND NOT public.can_intranet_action(p_page,'validate') THEN RAISE EXCEPTION 'module_owner_forbidden' USING ERRCODE='42501'; END IF;
  UPDATE public.intranet_records SET title=btrim(p_title),payload=p_payload,owner_id=p_owner,due_date=p_due,priority=p_priority,visibility=p_visibility,document_ids=p_documents,
  revision=revision+1,updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO saved;
 END IF;
 INSERT INTO public.intranet_record_events(record_id,actor_id,kind,before_state,after_state)VALUES(saved.id,actor,CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END,CASE WHEN p_id IS NOT NULL THEN to_jsonb(original) END,to_jsonb(saved));
 IF saved.owner_id IS NOT NULL AND saved.owner_id<>actor AND (p_id IS NULL OR saved.owner_id IS DISTINCT FROM original.owner_id) THEN
 INSERT INTO public.notifications(user_id,title,message,type,action_url,metadata)SELECT saved.owner_id,'Dossier attribué',saved.title,'info',definition->>'path'||'?record='||saved.id::text,jsonb_build_object('record_id',saved.id)FROM public.intranet_modules WHERE page_id=p_page;
 END IF;
 RETURN to_jsonb(saved);
END;
$$;
CREATE OR REPLACE FUNCTION public.transition_intranet_record(p_id uuid,p_expected_revision bigint,p_status text,p_note text DEFAULT '')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); original public.intranet_records%ROWTYPE; saved public.intranet_records%ROWTYPE; levels integer; decision boolean;
BEGIN
 SELECT * INTO original FROM public.intranet_records WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR NOT public.can_read_intranet_record(original) THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
 IF p_expected_revision IS NULL OR original.revision<>p_expected_revision THEN RAISE EXCEPTION 'module_record_changed' USING ERRCODE='40001'; END IF;
 IF p_status IS NULL OR p_status NOT IN ('draft','submitted','reviewed','approved','rejected','archived') OR char_length(coalesce(p_note,''))>5000 THEN RAISE EXCEPTION 'invalid_module_transition' USING ERRCODE='22023'; END IF;
 SELECT (definition->>'approvalLevels')::integer INTO levels FROM public.intranet_modules WHERE page_id=original.page_id;
 decision:=p_status IN ('approved','reviewed','rejected') OR (p_status='draft' AND original.status IN ('approved','reviewed','submitted'));
 IF decision THEN
  IF NOT public.can_intranet_action(original.page_id,'validate') OR actor=original.created_by OR actor=original.owner_id THEN RAISE EXCEPTION 'module_approval_forbidden' USING ERRCODE='42501'; END IF;
 ELSE
  IF NOT public.can_intranet_action(original.page_id,CASE WHEN p_status='archived' THEN 'delete' ELSE 'update' END) THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
  IF actor<>original.created_by AND actor IS DISTINCT FROM original.owner_id AND NOT public.can_intranet_action(original.page_id,'validate') THEN RAISE EXCEPTION 'module_owner_forbidden' USING ERRCODE='42501'; END IF;
 END IF;
 IF NOT ((original.status IN ('draft','rejected') AND p_status IN ('submitted','archived','draft')) OR
 (original.status='submitted' AND p_status IN ('reviewed','approved','rejected','draft')) OR
 (original.status='reviewed' AND p_status IN ('approved','rejected','draft')) OR
 (original.status='approved' AND p_status IN ('archived','draft'))) OR p_status=original.status THEN RAISE EXCEPTION 'invalid_module_transition' USING ERRCODE='22023'; END IF;
 IF p_status='approved' AND levels=2 AND (original.status<>'reviewed' OR original.first_reviewer=actor) THEN RAISE EXCEPTION 'module_second_approval_required' USING ERRCODE='42501'; END IF;
 IF p_status='reviewed' AND levels<>2 THEN RAISE EXCEPTION 'invalid_module_transition' USING ERRCODE='22023'; END IF;
 IF p_status IN ('rejected','draft') AND length(btrim(coalesce(p_note,'')))=0 THEN RAISE EXCEPTION 'module_decision_note_required' USING ERRCODE='22023'; END IF;
 UPDATE public.intranet_records SET status=p_status,revision=revision+1,updated_at=clock_timestamp(),
 first_reviewer=CASE WHEN p_status='reviewed' THEN actor WHEN p_status IN ('draft','submitted') THEN NULL ELSE first_reviewer END,
 approved_by=CASE WHEN p_status='approved' THEN actor WHEN p_status IN ('draft','submitted') THEN NULL ELSE approved_by END WHERE id=p_id RETURNING * INTO saved;
 INSERT INTO public.intranet_record_events(record_id,actor_id,kind,note,before_state,after_state)VALUES(p_id,actor,p_status,nullif(btrim(p_note),''),to_jsonb(original),to_jsonb(saved));
 RETURN to_jsonb(saved);
END;
$$;
CREATE OR REPLACE FUNCTION public.comment_intranet_record(p_id uuid,p_note text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.intranet_records%ROWTYPE; result uuid;
BEGIN
 SELECT * INTO r FROM public.intranet_records WHERE id=p_id FOR SHARE;
 IF NOT FOUND OR NOT public.can_read_intranet_record(r) OR NOT public.can_intranet_action(r.page_id,'update') OR r.status='archived' THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
 IF length(btrim(coalesce(p_note,''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'invalid_module_comment' USING ERRCODE='22023'; END IF;
 INSERT INTO public.intranet_record_events(record_id,actor_id,kind,note)VALUES(p_id,auth.uid(),'comment',btrim(p_note))RETURNING id INTO result;RETURN result;
END;
$$;
REVOKE ALL ON FUNCTION public.can_intranet_action(text,text),public.get_intranet_permissions(),public.can_read_intranet_record(public.intranet_records),public.list_intranet_people(),public.list_intranet_records(text,text,text,integer),public.save_intranet_record(uuid,text,bigint,uuid,text,jsonb,uuid,date,text,text,uuid[]),public.transition_intranet_record(uuid,bigint,text,text),public.comment_intranet_record(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_intranet_action(text,text),public.get_intranet_permissions(),public.can_read_intranet_record(public.intranet_records),public.list_intranet_people(),public.list_intranet_records(text,text,text,integer),public.save_intranet_record(uuid,text,bigint,uuid,text,jsonb,uuid,date,text,text,uuid[]),public.transition_intranet_record(uuid,bigint,text,text),public.comment_intranet_record(uuid,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.validate_intranet_payload(text,jsonb) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_intranet_record_events(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.intranet_records r WHERE r.id=p_id AND public.can_read_intranet_record(r)) THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF;
 RETURN (SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.created_at DESC,e.id),'[]'::jsonb)FROM public.intranet_record_events e WHERE e.record_id=p_id);
END;
$$;
REVOKE ALL ON FUNCTION public.list_intranet_record_events(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.list_intranet_record_events(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_intranet_record(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r public.intranet_records%ROWTYPE;
BEGIN SELECT * INTO r FROM public.intranet_records WHERE id=p_id;
 IF NOT FOUND OR NOT public.can_read_intranet_record(r) THEN RAISE EXCEPTION 'module_forbidden' USING ERRCODE='42501'; END IF; RETURN to_jsonb(r); END;
$$;
REVOKE ALL ON FUNCTION public.get_intranet_record(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_intranet_record(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.intranet_module_summary(p_scope text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (
 SELECT m.page_id,count(r.id) total,count(r.id)FILTER(WHERE r.status IN ('submitted','reviewed'))pending,
 count(r.id)FILTER(WHERE r.due_date<current_date AND r.status NOT IN ('approved','archived'))late
 FROM public.intranet_modules m LEFT JOIN public.intranet_records r ON r.page_id=m.page_id AND public.can_read_intranet_record(r)
 WHERE m.definition->>'scope'=p_scope AND public.can_intranet_action(m.page_id,'read') GROUP BY m.page_id)x;
$$;
REVOKE ALL ON FUNCTION public.intranet_module_summary(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.intranet_module_summary(text) TO authenticated,service_role;
